    const loading = track(() => auth.value.loading);
    const userId = track(() => auth.value.user?.id);
    if (loading) return;

    // Already filed a brief → the writer belongs at the desk, not here.
    if (loadProjectBrief()) {
      void nav("/editor/");
      return;
