              name: persona.name,
              role: persona.role,
              description: persona.description,
              focus: persona.focus,
              color: persona.color,
              icon: persona.icon,
            },
            userMessage,
            draftText: "",
            brief: brief ?? null,
            priorMessages,
          });
          replyText = (res as { reply?: string })?.reply ?? "";
        }

        if (!replyText) {
          replyText = fallbackReply(persona, comment);
        }
        const reply: UserCommentReply = {
          id: `r-${Date.now()}`,
          author: persona.name,
          authorKind: "persona",
          personaId: persona.id,
          color: persona.color,
          text: replyText,
          createdAt: Date.now(),
        };
        const all = await appendUserCommentReply(commentId, reply);
        store.comments = all;
        window.dispatchEvent(new CustomEvent("twyne:user-comments-changed"));
      } catch (err) {
        store.askError = (err as Error).message ?? "Editor unavailable.";
      } finally {
        store.isAskingEditor = false;
        store.askPersonaFor = null;
        store.askPersonaId = null;
      }
    });

    const unresolved = store.comments.filter((c) => {
      if (c.resolved) return false;
      // The "ghosts only" filter shows threads whose anchor
      // passage is gone from the manuscript. Ghosts come first
      // so the writer sees the orphans before anything else.
      if (store.ghostsOnly && !store.ghostIds.has(c.id)) return false;
      return true;
    });
    answers: ProjectInterviewAnswers;
    attachments: DossierAttachment[];
  }) => {
    if (!store.brief) return;
    const next = createProjectBrief(answers, store.brief, attachments);
    saveProjectBrief(next);
    void nav("/editor/");
  });

  const runDossierCheck = $(async () => {
    if (!store.brief) return;
    store.dossierCheckLoading = true;
    store.dossierCheckError = null;
    store.showDossierCheck = true;
    try {
      const raw = await loadAiSettingsFromIdb();
      const settings = raw ?? {
        advancedMode: false,
        providers: [],
        defaultProviderId: null,
        perFeature: {},
        showProviderTags: false,
      };
      if (!hasConfiguredAiProvider(settings)) {
        store.dossierCheckError =
          "Reading the draft needs a configured AI provider. Add one in Settings.";
        store.dossierCheckLoading = false;
        return;
      }
      const result = await runClientDossierCheck(
        { brief: store.brief, draftText: store.draftText || null },
        settings,
      );
      store.dossierCheck = result;
    } catch (err) {
      store.dossierCheckError = (err as Error).message ?? "The check failed.";
    } finally {
      store.dossierCheckLoading = false;
    }
  });

  const applyObservation = $((obs: DossierObservation) => {
    if (!store.brief || !obs.suggested) return;
    const updated: ProjectInterviewAnswers = {
      ...store.brief.answers,
      [obs.field]: obs.suggested,
    };
    const next: ProjectBrief = {
      ...store.brief,
      answers: updated,
      updatedAt: Date.now(),
    };
    saveProjectBrief(next);
    store.brief = next;
    if (store.dossierCheck) {
      store.dossierCheck = {
        ...store.dossierCheck,
        observations: store.dossierCheck.observations.filter((o) => o !== obs),
      };
    }
  });

  const dismissObservation = $((obs: DossierObservation) => {
    if (store.dossierCheck) {
      store.dossierCheck = {
        ...store.dossierCheck,
        observations: store.dossierCheck.observations.filter((o) => o !== obs),
      };
    }
  });

  if (!store.hydrated) {
    return (
      <div class="flex h-screen items-center justify-center bg-[var(--color-paper)] text-[var(--color-ink-muted)]">
