136	/**
137	 * Resolve the effective numeric page margins (in rem) for a layout, applying
138	 * sensible fallbacks so documents saved before numeric margins existed still
139	 * render correctly.
140	 */
141	export function resolveMargins(layout: LayoutSettings): {
142	  x: number;
143	  top: number;
144	  bottom: number;
