export interface DossierAttachment {
  id: string;
  kind: "document" | "link";
  title: string;
  /** kind === "link" (or an optional source URL for a document). */
  url?: string;
  /** kind === "document": pasted/uploaded text, capped ~2000 chars. */
  text?: string;
