               </p>
               <button
                 onClick$={() => {
                   store.showDossierCheck = false;
                 }}
                 class="text-[0.6rem] tracking-[0.15em] uppercase text-[var(--color-ink-muted)] hover:text-[var(--color-ink)]"
                 style={{ fontFamily: "var(--font-typewriter)" }}
               >
