export const CommentsPanel = component$(
  ({
    brief,
    activeFolioId,
    initialComments,
    collaborators,
  }: CommentsPanelProps) => {
    const clientSig = useConvexClient();
    const store = useStore<CommentsStore>({
      comments: initialComments ?? [],
      newCommentText: "",
      replyingTo: null,
      replyDrafts: {},
      askPersonaFor: null,
      askPersonaId: null,
      isAskingEditor: false,
      askError: null,
