import { component$, type PropFunction } from "@builder.io/qwik";
import type {
  DossierAttachment,
  DossierCheckResult,
  DossierProbe,
  ProjectInterviewAnswers,
} from "../../types";
import { isAnswered, probeSummaryLine } from "../../utils/dossier-probes";

const FIELD_LABELS: Record<keyof ProjectInterviewAnswers, string> = {
  workingTitle: "Working title",
  format: "Format",
  audience: "Audience",
  goal: "Goal",
  tone: "Tone",
  constraints: "Non-negotiables",
  successSignal: "Success signal",
};

const FIELD_ORDER: Array<keyof ProjectInterviewAnswers> = [
  "workingTitle",
  "format",
  "audience",
  "goal",
  "tone",
  "constraints",
  "successSignal",
];

interface DossierPreviewProps {
  answers: ProjectInterviewAnswers;
  probes: DossierProbe[];
  attachments: DossierAttachment[];
  activeField?: keyof ProjectInterviewAnswers;
  existingMaterialWords?: number;
  mode: "first-run" | "refine";
  draftReview?: DossierCheckResult | null;
  draftReviewLoading?: boolean;
  draftReviewError?: string | null;
  onReadDraft$?: PropFunction<() => void>;
  onApplyObservation$?: PropFunction<(index: number) => void>;
  onDismissObservation$?: PropFunction<(index: number) => void>;
}

/**
 * The live dossier occupies the form's supporting column after the opening
 * question. It is useful working context, not a second summary card: every
 * field is visible, the active field is identified, answered Particulars are
 * retained in order, and draft drift is reviewed and applied in place.
 */
export const DossierPreview = component$((props: DossierPreviewProps) => {
  const answeredProbes = props.probes.filter(isAnswered);
  const completedFields = FIELD_ORDER.filter(
    (field) => props.answers[field].trim().length > 0,
  ).length;
  const hasReview = props.draftReview !== undefined || !!props.onReadDraft$;

  return (
    <section aria-labelledby="atr-title">
      <div class="flex flex-wrap items-center justify-between gap-3">
        <div>
          <p class="dept-label">
            {props.mode === "refine" ? "Edition · Revised" : "Working copy"}
          </p>
          <h1
            id="atr-title"
            class="mt-1 text-[1.85rem] leading-tight text-[var(--color-ink)]"
            style={{
              fontFamily: "var(--font-display)",
              fontWeight: 700,
              letterSpacing: "-0.015em",
            }}
          >
            Dossier preview
          </h1>
        </div>
        <span class="stamp">
          {completedFields} / {FIELD_ORDER.length} filed
        </span>
      </div>

      <p
        class="mt-3 max-w-[62ch] text-sm leading-6 text-[var(--color-ink-light)]"
        style={{ fontFamily: "var(--font-serif)" }}
      >
        This is the working brief every editor will read. It updates as you
        answer, keeps unresolved decisions visible, and holds any draft changes
        you choose to file.
      </p>

      <dl class="mt-5 grid gap-2 sm:grid-cols-2">
        {FIELD_ORDER.map((field) => {
          const active = props.activeField === field;
          return (
            <div
              key={field}
              class={`min-w-0 border p-3 ${
                active
                  ? "border-[var(--color-vermilion)] bg-[var(--color-paper)]"
                  : "border-[var(--color-paper-3)] bg-[var(--color-paper-soft)]"
              }`}
              aria-current={active ? "step" : undefined}
            >
              <dt class="dept-label">{FIELD_LABELS[field]}</dt>
              <dd
                class="mt-1 text-[0.82rem] leading-5 text-[var(--color-ink-light)] break-words"
                style={{ fontFamily: "var(--font-serif)" }}
              >
                {props.answers[field] || (
                  <span class="italic text-[var(--color-ink-muted)]">
                    Not decided yet.
                  </span>
                )}
              </dd>
            </div>
          );
        })}
      </dl>

      <div class="mt-4 grid gap-3 sm:grid-cols-2">
        <section class="border border-[var(--color-paper-3)] bg-[var(--color-paper-soft)] p-3">
          <p class="dept-label">Particulars</p>
          {answeredProbes.length > 0 ? (
            <ol class="mt-2 space-y-2">
              {answeredProbes.map((probe, index) => (
                <li
                  key={probe.id}
                  class="text-[0.75rem] leading-5 text-[var(--color-ink-light)]"
                  style={{ fontFamily: "var(--font-serif)" }}
                >
                  <span
                    class="mr-1 text-[var(--color-vermilion)]"
                    style={{ fontFamily: "var(--font-typewriter)" }}
                  >
                    {index + 1}.
                  </span>
                  {probeSummaryLine(probe)}
                </li>
              ))}
            </ol>
          ) : (
            <p
              class="mt-2 text-[0.75rem] leading-5 text-[var(--color-ink-muted)]"
              style={{ fontFamily: "var(--font-serif)" }}
            >
              The Particulars questions will sharpen the softest parts of this
              brief.
            </p>
          )}
        </section>

        <section class="border border-[var(--color-paper-3)] bg-[var(--color-paper-soft)] p-3">
          <p class="dept-label">Material on file</p>
          <dl class="mt-2 space-y-1 text-[0.75rem] text-[var(--color-ink-light)]">
            <div class="flex items-baseline justify-between gap-3">
              <dt>Starting material</dt>
              <dd>{props.existingMaterialWords ?? 0} words</dd>
            </div>
            <div class="flex items-baseline justify-between gap-3">
              <dt>References</dt>
              <dd>{props.attachments.length}</dd>
            </div>
            <div class="flex items-baseline justify-between gap-3">
              <dt>Answered particulars</dt>
              <dd>{answeredProbes.length}</dd>
            </div>
          </dl>
        </section>
      </div>

      {hasReview && (
        <section class="mt-4 border border-[var(--color-paper-3)] bg-[var(--color-paper)] p-4">
          <div class="flex flex-wrap items-start justify-between gap-3">
            <div>
              <p class="dept-label">Draft alignment</p>
              <h2
                class="mt-1 text-base text-[var(--color-ink)]"
                style={{
                  fontFamily: "var(--font-display)",
                  fontWeight: 650,
                }}
              >
                Has the manuscript outgrown the brief?
              </h2>
              <p
                class="mt-1 max-w-[48ch] text-[0.75rem] leading-5 text-[var(--color-ink-muted)]"
                style={{ fontFamily: "var(--font-serif)" }}
              >
                Read the current draft against what is filed here. Nothing
                changes until you apply a suggestion.
              </p>
            </div>
            {props.onReadDraft$ && (
              <button
                type="button"
                onClick$={props.onReadDraft$}
                disabled={props.draftReviewLoading}
                class="btn-press disabled:opacity-40"
              >
                {props.draftReviewLoading
                  ? "Reading draft…"
                  : "Read my draft"}
              </button>
            )}
          </div>

          {props.draftReviewLoading && (
            <p
              class="mt-3 flex items-center gap-2 text-[0.75rem] text-[var(--color-ink-muted)]"
              style={{ fontFamily: "var(--font-typewriter)" }}
              role="status"
            >
              <span
                class="h-2 w-2 rounded-full bg-[var(--color-mustard)] interview-stream-pulse"
                aria-hidden="true"
              />
              Comparing the manuscript with all seven dossier fields.
            </p>
          )}

          {props.draftReviewError && (
            <p
              class="mt-3 border border-[var(--color-vermilion)] bg-[color-mix(in_srgb,var(--color-vermilion)_7%,var(--color-paper))] p-3 text-[0.78rem] leading-5 text-[var(--color-ink)]"
              style={{ fontFamily: "var(--font-serif)" }}
              role="alert"
            >
              {props.draftReviewError}
            </p>
          )}

          {!props.draftReviewLoading &&
            props.draftReview &&
            props.draftReview.observations.length === 0 && (
              <p
                class="mt-3 border border-[var(--color-accent-green)] bg-[color-mix(in_srgb,var(--color-accent-green)_8%,var(--color-paper))] p-3 text-[0.78rem] leading-5 text-[var(--color-ink-light)]"
                style={{ fontFamily: "var(--font-serif)" }}
                role="status"
              >
                No drift found. The current manuscript still matches the
                dossier.
              </p>
            )}

          {props.draftReview?.observations.map((observation, index) => (
            <article
              key={`${observation.field}-${observation.suggested}-${index}`}
              class="mt-3 border border-[var(--color-paper-3)] bg-[var(--color-paper-soft)] p-3"
            >
              <p class="dept-label">{FIELD_LABELS[observation.field]}</p>
              <p
                class="mt-2 text-[0.8rem] leading-5 text-[var(--color-ink)]"
                style={{ fontFamily: "var(--font-serif)" }}
              >
                {observation.reason}
              </p>
              <dl class="mt-3 grid gap-2 text-[0.75rem] sm:grid-cols-2">
                <div class="border border-[var(--color-paper-3)] bg-[var(--color-paper)] p-2.5">
                  <dt class="dept-label">Filed now</dt>
                  <dd class="mt-1 leading-5 text-[var(--color-ink-light)]">
                    {observation.current ||
                      props.answers[observation.field] ||
                      "Not filed"}
                  </dd>
                </div>
                <div class="border border-[var(--color-mustard)] bg-[var(--color-paper)] p-2.5">
                  <dt class="dept-label">Suggested</dt>
                  <dd class="mt-1 leading-5 text-[var(--color-ink)]">
                    {observation.suggested}
                  </dd>
                </div>
              </dl>
              <div class="mt-3 flex flex-wrap items-center gap-2">
                {observation.suggested && props.onApplyObservation$ && (
                  <button
                    type="button"
                    onClick$={() => props.onApplyObservation$?.(index)}
                    class="btn-press"
                  >
                    Apply to dossier
                  </button>
                )}
                {props.onDismissObservation$ && (
                  <button
                    type="button"
                    onClick$={() => props.onDismissObservation$?.(index)}
                    class="btn-paper"
                  >
                    Dismiss suggestion
                  </button>
                )}
              </div>
            </article>
          ))}
        </section>
      )}
    </section>
  );
});

